package com.wizzadrds.theworldremembers;
import com.wizzadrds.theworldremembers.knowledge.*; import net.fabricmc.fabric.api.gametest.v1.GameTest; import net.minecraft.gametest.framework.GameTestHelper; import net.minecraft.world.entity.EntityTypes;
public final class Phase7KnowledgeGameTest{@GameTest public void witnessKnowledgeAndConversation(GameTestHelper c){var a=c.spawn(EntityTypes.VILLAGER,2,1,2);var b=c.spawn(EntityTypes.VILLAGER,3,1,2);var subject=c.spawn(EntityTypes.VILLAGER,4,1,2);c.runAtTickTime(1,()->{subject.kill();c.runAtTickTime(2,()->{var k=KnowledgeManager.get(c.getLevel().getServer());var f=k.facts(a.getUUID()).stream().filter(x->x.subject().equals(subject.getUUID())).findFirst();if(f.isEmpty()||f.get().provenance()!=KnowledgeProvenance.DIRECT){c.fail("Witness knowledge missing");return;}k.report(a.getUUID(),b.getUUID(),"npc_died",subject.getUUID(),c.getLevel().getGameTime());var r=k.facts(b.getUUID()).stream().filter(x->x.subject().equals(subject.getUUID())).findFirst();if(r.isEmpty()||r.get().provenance()!=KnowledgeProvenance.REPORTED||r.get().confidence()>=1){c.fail("Reported knowledge did not degrade");return;}c.succeed();});});}}
